// Writes one overview page per lesson folder: two cards, Lý thuyết (lesson) and Thực hành (practice).
// Generated files are gitignored. Edit the lesson and practice files instead.
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { listBatches, listLessons, ROOT } from './lessons.mjs';

const esc = (s = '') => s.replace(/[&<>{}]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '{': '&#123;', '}': '&#125;' })[c]);
const GENERATED = '-overview.mdx';

const lessons = listLessons();
const batches = listBatches();

// drop overview files whose lesson no longer exists
const wanted = new Set(lessons.map((l) => join(l.materials, `${l.slug}${GENERATED}`)));
for (const dir of readdirSync(join(ROOT, 'lessons'), { withFileTypes: true })) {
	if (!dir.isDirectory() || !/^\d+-/.test(dir.name)) continue;
	const mats = join(ROOT, 'lessons', dir.name, 'materials');
	if (!existsSync(mats)) continue;
	for (const f of readdirSync(mats).filter((f) => f.endsWith(GENERATED))) {
		if (!wanted.has(join(mats, f))) rmSync(join(mats, f));
	}
}

for (const l of lessons) {
	const title = `Lesson ${l.num}: ${l.lesson.title}`;
	// card text is Vietnamese: the summary field. subtitle is a fallback, and flagged because it is often English
	const desc = l.lesson.summary || l.lesson.subtitle || l.lesson.title;
	if (!l.lesson.summary) console.warn(`lesson ${l.num}: no summary field, card text falls back to the English subtitle`);
	const cards = [
		`  <a class="lesson-card" href="../lesson">
    <strong class="lesson-card__title">Lý thuyết</strong>
    <span class="lesson-card__text">${esc(desc)}</span>
  </a>`,
	];
	if (l.lesson.slides) {
		cards.push(`  <a class="lesson-card" href="${esc(l.lesson.slides)}" target="_blank" rel="noopener">
    <strong class="lesson-card__title">Slides</strong>
    <span class="lesson-card__text">Slide deck của buổi này ↗</span>
  </a>`);
	}
	if (l.practice) {
		cards.push(`  <a class="lesson-card" href="../practice">
    <strong class="lesson-card__title">Thực hành</strong>
    <span class="lesson-card__text">${esc(l.practice.summary || l.practice.title)}</span>
  </a>`);
	}
	if (l.reference) {
		cards.push(`  <a class="lesson-card" href="../reference">
    <strong class="lesson-card__title">Tài liệu tham khảo</strong>
    <span class="lesson-card__text">Link đọc thêm, method cards và ví dụ cho buổi này</span>
  </a>`);
	}
	// playback belongs to a batch; the lesson only links to it, one short link per batch
	const taught = batches.filter((b) => b.playbacks.some((p) => p.slug === l.slug));
	const playback = taught.length
		? `\n<p class="lesson-playback">Playback: ${taught.map((b) => `<a href="../../../classes/${b.slug}/playback/${l.slug}/">${esc(b.label)}</a>`).join(' · ')}</p>\n`
		: '';
	const body = `---
title: "${esc(title).replace(/"/g, '\\"')}"
description: "${esc(desc).replace(/"/g, '\\"')}"
tableOfContents: false
---

{/* Generated by site/scripts/lesson-overviews.mjs. Edit the lesson files, not this page. */}

<div class="lesson-cards">
${cards.join('\n')}
</div>
${playback}`;
	writeFileSync(join(l.materials, `${l.slug}${GENERATED}`), body);
}

console.log(`lesson overviews: ${lessons.length} lessons`);

// Per batch, generated into classes/<batch>/generated/: the batch overview (about.md, then Playback and Mentees) and one page per mentee.
// Mentees are not in the sidebar; the overview is the way in, and each mentee page links to the previous and next one.
const page = (title, description, body, toc = false) => `---
title: "${esc(title).replace(/"/g, '\\"')}"
description: "${esc(description).replace(/"/g, '\\"')}"
tableOfContents: ${toc}
---

{/* Generated by site/scripts/lesson-overviews.mjs. Edit about.md, mentees.md and playback/, not this page. */}

${body}
`;

for (const b of batches) {
	const out = join(b.dir, 'generated');
	rmSync(out, { recursive: true, force: true });
	mkdirSync(join(out, 'mentees'), { recursive: true });

	const playback = b.playbacks.length
		? `<div class="lesson-cards">
${b.playbacks
	.map(
		(p) => `  <a class="lesson-card" href="playback/${p.slug}/">
    <span class="lesson-card__kicker">Lesson ${p.num}</span>
    <strong class="lesson-card__title">${esc(lessons.find((l) => l.slug === p.slug)?.lesson.title || p.meta.title || p.slug)}</strong>
    <span class="lesson-card__text">${p.meta.video ? 'Video, slides và ghi chú' : 'Chưa có video'}</span>
  </a>`,
	)
	.join('\n')}
</div>`
		: 'Chưa có playback nào.';
	const mentees = b.mentees.length
		? `Bấm vào tên để mở workspace của bạn đó.

<div class="lesson-cards">
${b.mentees.map((m) => `  <a class="lesson-card" href="mentees/${m.slug}/"><strong class="lesson-card__title">${esc(m.name)}</strong></a>`).join('\n')}
</div>`
		: 'Chưa có workspace nào được gửi.';
	// about.md is the mentor's own text (start date, schedule, mentors); the student count is counted, not typed
	// shortcut: about.md is pasted into an MDX page, so a bare `{` or `<` in it breaks the build. Render it as markdown if that bites.
	const aboutFile = join(b.dir, 'about.md');
	const about = existsSync(aboutFile) ? readFileSync(aboutFile, 'utf8').replace(/^---\n[\s\S]*?\n---\n/, '').replace(/^# .*\n/, '').trim() : '';
	writeFileSync(
		join(out, 'index.mdx'),
		page(
			b.label,
			`Tổng quan, playback và workspace của mentee, ${b.label}`,
			`## Overview

${about}

- **Số học viên:** ${b.mentees.length}

## Playback

${playback}

## Mentees

${mentees}`,
		),
	);

	b.mentees.forEach((m, i) => {
		const prev = b.mentees[i - 1];
		const next = b.mentees[i + 1];
		const nav = [
			prev && `<a href="../${prev.slug}/">← ${esc(prev.name)}</a>`,
			`<a href="../../#mentees">Tất cả mentees (${i + 1}/${b.mentees.length})</a>`,
			next && `<a href="../${next.slug}/">${esc(next.name)} →</a>`,
			`<a href="${esc(m.url)}" target="_blank" rel="noopener">Mở tab mới ↗</a>`,
		].filter(Boolean);
		writeFileSync(
			join(out, 'mentees', `${m.slug}.mdx`),
			page(
				m.name,
				`Workspace của ${m.name}, ${b.label}`,
				`<nav class="workspace-nav" aria-label="Mentees">${nav.join('')}</nav>

<iframe class="workspace" src="${esc(m.url)}" title="Workspace của ${esc(m.name)}" loading="lazy"></iframe>`,
			),
		);
	});
}
console.log(`class pages: ${batches.length} batches, ${batches.reduce((n, b) => n + b.mentees.length, 0)} mentees`);
